CREATE PROCEDURE [dbo].[up_BDEE_Update] (
  @UniqueId bigint,
  @CODEVER varchar(20),
  @DATA varchar(30),
  @DESCR varchar(40),
  @URLFR varchar(100),
  @URLEN varchar(100)
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO BDEE (
    [CODEVER],
    [DATA],
    [DESCR],
    [URLFR],
    [URLEN],
    SysDate)
  VALUES (
    @CODEVER,
    @DATA,
    @DESCR,
    @URLFR,
    @URLEN,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    BDEE
  SET
    [CODEVER] = @CODEVER,
    [DATA] = @DATA,
    [DESCR] = @DESCR,
    [URLFR] = @URLFR,
    [URLEN] = @URLEN,
    SysDate = GETDATE()
  WHERE
    UniqueId = @UniqueId

  --Return updated ID
  RETURN @UniqueId
END
GO

CREATE PROCEDURE [dbo].[up_BDEE_Delete] (
  @UniqueId bigint
) AS

DELETE FROM BDEE WHERE UniqueId = @UniqueId
GO

