  @SOU_ID varchar(20),
  @DIV_ID varchar(3),
  @DESC varchar(40)
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO SOUDIV (
    [SOU_ID],
    [DIV_ID],
    [DESC],
    SysDate)
  VALUES (
    @SOU_ID,
    @DIV_ID,
    @DESC,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    SOUDIV
  SET
    [SOU_ID] = @SOU_ID,
    [DIV_ID] = @DIV_ID,
    [DESC] = @DESC,
    SysDate = GETDATE()
  WHERE
    UniqueId = @UniqueId

  --Return updated ID
  RETURN @UniqueId
END
GO

CREATE PROCEDURE [dbo].[up_SOUDIV_Delete] (
  @UniqueId bigint
) AS

DELETE FROM SOUDIV WHERE UniqueId = @UniqueId
GO

