IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.ROUTINES WHERE Routine_Type = 'PROCEDURE' AND Specific_Name = 'up_UM_USERS_Update')
  DROP PROCEDURE up_UM_USERS_Update
GO

CREATE PROCEDURE [dbo].[up_UM_USERS_Update] (
  @UniqueId bigint,
  @USER_ID varchar(20),
  @NAME varchar(30),
  @EMAIL varchar(30),
  @BRANCH_ID varchar(20),
  @ROLE_ID INT,
  @VALIDATEFROM INT,
  @PSW varchar(12),
  @ACTIVE bit,
  @SORTBRANCH_CODE varchar(20),
  @OWC varchar(2)
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO UM_USERS (
    [USER_ID],
    [NAME],
    [EMAIL],
    [BRANCH_ID],
    [ROLE_ID],
    [VALIDATEFROM],
    [PSW],
    [ACTIVE],
    [SORTBRANCH_CODE],
    [OWC],
    SysDate)
  VALUES (
    @USER_ID,
    @NAME,
    @EMAIL,
    @BRANCH_ID,
    @ROLE_ID,
    @VALIDATEFROM,
    @PSW,
    @ACTIVE,
    @SORTBRANCH_CODE,
    @OWC,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    UM_USERS
  SET
    [USER_ID] = @USER_ID,
    [NAME] = @NAME,
    [EMAIL] = @EMAIL,
    [BRANCH_ID] = @BRANCH_ID,
    [ROLE_ID] = @ROLE_ID,
    [VALIDATEFROM] = @VALIDATEFROM,
    [PSW] = @PSW,
    [ACTIVE] = @ACTIVE,
    [SORTBRANCH_CODE] = @SORTBRANCH_CODE,
    [OWC] = @OWC,
    SysDate = GETDATE()
  WHERE
    UniqueId = @UniqueId

  --Return updated ID
  RETURN @UniqueId
END
GO


