ALTER PROCEDURE [dbo].[up_ENSEMBLE_Update] (
  @UniqueId bigint,
  @ENS_ID varchar(20),
  @CLEPERS varchar(20),
  @DESC varchar(60),    -- 2012-01-19 EMadore : V3 -> Passage de 40 à 60 chars
  @COUUM varchar(2),
  @PROFIT float,
  @TEMPSEC float,
  @TEMPUNI float,
  @TEMPUM varchar(2),
  @DATECREE datetime,
  @OLDESTPROD datetime,
  @SYSTEM bit,
  @USES_DISC bit
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO ENSEMBLE (
    [ENS_ID],
    [CLEPERS],
    [DESC],
    [COUUM],
    [PROFIT],
    [TEMPSEC],
    [TEMPUNI],
    [TEMPUM],
    [DATECREE],
    [OLDESTPROD],
    [SYSTEM],
    [USES_DISC],
    SysDate)
  VALUES (
    @ENS_ID,
    @CLEPERS,
    @DESC,
    @COUUM,
    @PROFIT,
    @TEMPSEC,
    @TEMPUNI,
    @TEMPUM,
    @DATECREE,
    @OLDESTPROD,
    @SYSTEM,
    @USES_DISC,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    ENSEMBLE
  SET
    [ENS_ID] = @ENS_ID,
    [CLEPERS] = @CLEPERS,
    [DESC] = @DESC,
    [COUUM] = @COUUM,
    [PROFIT] = @PROFIT,
    [TEMPSEC] = @TEMPSEC,
    [TEMPUNI] = @TEMPUNI,
    [TEMPUM] = @TEMPUM,
    [DATECREE] = @DATECREE,
    [OLDESTPROD] = @OLDESTPROD,
    [SYSTEM] = @SYSTEM,
    [USES_DISC] = @USES_DISC,
    SysDate = GETDATE()
  WHERE
    UniqueId = @UniqueId

  --Return updated ID
  RETURN @UniqueId
END

GO
