ALTER PROCEDURE [dbo].[up_FACLOTS_Update] (
  @UniqueId bigint,
  @SOU_ID varchar(20),
  @LOTS_ID varchar(20),
  @DESC varchar(60),        -- 2012-01-19 EMadore V3 : Passage de 40 à 60 chars
  @QTETOT float,
  @QTETOTSECT float,
  @CALCTIMSTP varchar(14),
  @COUUM varchar(2),
  @TEMPUNI float,
  @TEMPUM varchar(2),
  @DATECREE datetime,
  @OLDESTPROD datetime,
  @CLEPERS varchar(40),
  @PROFIT float,
  @COUTANTSEL int,
  @COUTANT1 float,
  @COUTANT2 float,
  @COUTANT3 float,
  @COUTANT4 float
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO FACLOTS (
    [SOU_ID],
    [LOTS_ID],
    [DESC],
    [QTETOT],
    [QTETOTSECT],
    [CALCTIMSTP],
    [COUUM],
    [TEMPUNI],
    [TEMPUM],
    [DATECREE],
    [OLDESTPROD],
    [CLEPERS],
    [PROFIT],
    [COUTANTSEL],
    [COUTANT1],
    [COUTANT2],
    [COUTANT3],
    [COUTANT4],
    SysDate)
  VALUES (
    @SOU_ID,
    @LOTS_ID,
    @DESC,
    @QTETOT,
    @QTETOTSECT,
    @CALCTIMSTP,
    @COUUM,
    @TEMPUNI,
    @TEMPUM,
    @DATECREE,
