IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.ROUTINES WHERE Routine_Type = 'PROCEDURE' AND Specific_Name = 'upbi_ReturnMessage')
  DROP PROCEDURE upbi_ReturnMessage
