  @ORDRE varchar(6),
  @DESCFRAIS varchar(50),
  @COUTUNI float,
  @FRAISUM varchar(2),
  @PROFIT float,
  @INCLSOU bit,
  @INCLFAC bit,
  @ACC_NO varchar (20),
  @SYSTEM bit
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO FRAIS (
    [ORDRE],
    [DESCFRAIS],
    [COUTUNI],
    [FRAISUM],
    [PROFIT],
    [INCLSOU],
    [INCLFAC],
    [ACC_NO],
    [SYSTEM],
    SysDate)
  VALUES (
    @ORDRE,
    @DESCFRAIS,
    @COUTUNI,
    @FRAISUM,
    @PROFIT,
    @INCLSOU,
    @INCLFAC,
    @ACC_NO,
    @SYSTEM,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
