CREATE PROCEDURE [dbo].[up_BDEE_Update] (
  @UniqueId bigint,
  @LVERSION	  int,
  @CODEVER	  varchar(20),
  @DATA       varchar(30),
  @NODIST	    varchar(12),
  @NOEEWIN	  varchar(6),
  @NOGEM	    varchar(6),
  @ISINT      bit,
  @DIVISIONPX varchar(2),
  @DIVISION	  varchar(3),
  @DESCR	    varchar(40),
  @URLFR	    varchar(100),
  @URLEN	    varchar(100),
  @ORDERURLFR varchar(200),
  @ORDERURLEN varchar(200),
  @PRICEURL   varchar(200),
  @AUTHURL    varchar(200),
  @AUTHGLOKEY varchar(64),
  @AUTHCLIKEY varchar(64),
  @URLMODE    char(1),
  @ISDEMO	    bit,
