CREATE PROCEDURE [dbo].[up_PriceUpdate_DiscontinueProducts] (
  @Division varchar(3),
  @UpdateDate datetime
) AS

UPDATE 
  PRODUITS
SET 
  DNR = 'Y',
  NOUVEAU = 'N'
WHERE
  PRO_ID LIKE @Division + '%'
  AND DATECOUT <> @UpdateDate
  AND LEN(PRO_ID) <> 20
GO

