CREATE PROCEDURE [dbo].[up_CATSTATUS_update] (
  @UniqueId bigint,
  @TYPECAT  varchar(3), 
  @ORDRE    varchar(6), 
  @LIBELEFR varchar(30), 
  @LIBELEEN varchar(30)  
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO CATSTATUS (
    TYPECAT, 
    ORDRE,
    LIBELEFR , 
    LIBELEEN,    
    SysDate
    )
  VALUES (
    @TYPECAT,
    @ORDRE,
    @LIBELEFR, 
    @LIBELEEN,  
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    CATSTATUS
  SET
    TYPECAT   = @TYPECAT,
    ORDRE     = @ORDRE,
    LIBELEFR  = @LIBELEFR,
    LIBELEEN  = @LIBELEEN,
    SysDate     = GETDATE()
  WHERE
    UniqueId = @UniqueId

  --Return updated ID
  RETURN @UniqueId
END
GO


