CREATE FUNCTION [dbo].fn_UM_GetNatureUnite(@CodeEN VARCHAR(1))
RETURNS VARCHAR(1)
AS BEGIN
  DECLARE @R VARCHAR(1)

  SELECT @R = P.[Type] 
  FROM Sys_Units P 
  WHERE P.CodeEN = @CodeEN

  RETURN @R

END
GO


