CREATE FUNCTION [dbo].fn_STR_AddAndSortChars (@aStr VARCHAR(200), @aNewStr VARCHAR(200))
RETURNS VARCHAR(40) 
AS BEGIN
    DECLARE @R VARCHAR(400) 

    SELECT  @R = dbo.fn_STR_Alphaorder ([dbo].[fn_Str_RemoveAllRepeatingChars](@aStr + @aNewStr)) ;
    RETURN  @R

END
GO

