CREATE PROCEDURE [dbo].sp_CalculCodeImpr(@SOU_ID VARCHAR(20), @PRO_ID  VARCHAR(20), @value  VARCHAR(36))
AS BEGIN
   if ( @value is not null ) AND (@value <> '')
   BEGIN
    UPDATE SOUPRO
      SET CODEIMPR = dbo.fn_STR_AddAndSortChars(CODEIMPR, @value) 
    WHERE   SOU_ID = @SOU_ID
    AND     PRO_ID = @PRO_ID 
   END
END
