CREATE PROCEDURE [dbo].[up_SOUWEBLOG_Update] (
  @UniqueId bigint,
  @SOU_ID varchar(20),
  @WEB_ID varchar(15),
  @TRF_DATE varchar(25),
  @RESULT varchar(10),
  @MESSAGE varchar(60)
) AS

IF @UniqueId IS NULL
BEGIN
  --Insert new data into table
  INSERT INTO SOUWEBLOG (
    [SOU_ID],
    [WEB_ID],
    [TRF_DATE],
    [RESULT],
    [MESSAGE],
    SysDate)
  VALUES (
    @SOU_ID,
    @WEB_ID,
    @TRF_DATE,
    @RESULT,
    @MESSAGE,
    GETDATE())

  --Return new ID
  RETURN @@IDENTITY
END ELSE
BEGIN
  --Update data into table
  UPDATE
    SOUWEBLOG
  SET
    [SOU_ID] = @SOU_ID,
    [WEB_ID] = @WEB_ID,
    [TRF_DATE] = @TRF_DATE,
    [RESULT] = @RESULT,
    [MESSAGE] = @MESSAGE,
    SysDate = GETDATE()
  WHERE
    UniqueId = @UniqueId

    -- Mise à jour du Last user updating SOUMIS
  exec dbo.sp_Update_SoumisUseSession @SOU_ID
  
  --Return updated ID
  RETURN @UniqueId
END
GO


