    [UMPLAN] = @UMPLAN,
    [TYPEPROF] = @TYPEPROF,
    [MATPROFDEF] = @MATPROFDEF,
    [TYPESRVPRO] = @TYPESRVPRO,
    [TAUXMD] = @TAUXMD,
    [NUMLOTEXP] = @NUMLOTEXP,
    [SYSTEM] = @SYSTEM,
    [USER1] = @USER1,
    [USER2] = @USER2,
    [EST_NAME] = @EST_NAME,
    [ACCTRANSNO] = @ACCTRANSNO,
    [PRJTRANSNO] = @PRJTRANSNO,
    [STATUTLIBF]  = @STATUTLIBF,
    [STATUTLIBE]  = @STATUTLIBE,	
    [USER_ID] = @USER_ID,
    [BRANCH_ID]  = @BRANCH_ID,
    [OWC]  = @OWC,	
    SysDate = GETDATE()
  WHERE
    UniqueId = @UniqueId

    -- Mise à jour du Last user updating SOUMIS
  exec dbo.sp_Update_SoumisUseSession @SOU_ID	

  --Return updated ID
  RETURN @UniqueId
END
GO

