CREATE FUNCTION dbo.fn_CastAE (@Input DECIMAL(18,6), @Precision INT)
RETURNS DECIMAL(18,6)
AS
BEGIN

  DECLARE @Output DECIMAL(18,6)
  Select @Output = ROUND(@Input, @Precision);
  Return @Output

END;
